export const DOE2_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/doe2-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getDoe2StdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(DOE2_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
